package common

import chisel3._
import chisel3.util._

// FIFO with configurable depth, 1 input, multiple outputs
class FifoIxO[T <: Data](gen: T, depth: Int, n: Int) extends Module {
  val io = IO(new Bundle {
    val enq = Flipped(Decoupled(gen))
    val deq = Vec(n, Decoupled(gen))
  })

  val q = Module(new Queue(gen, depth))
  q.io.enq <> io.enq
  // Only deq(0) connected, others tied off
  io.deq(0) <> q.io.deq
  for (i <- 1 until n) {
    io.deq(i).valid := false.B
    io.deq(i).bits := 0.U.asTypeOf(gen)
  }
}
