package common

import chisel3._
import chisel3.util._

// Integer divider (non-pipelined, iterative)
class IDiv(width: Int) extends Module {
  val io = IO(new Bundle {
    val dividend = Input(UInt(width.W))
    val divisor  = Input(UInt(width.W))
    val signed   = Input(Bool())
    val start    = Input(Bool())
    val quotient  = Output(UInt(width.W))
    val remainder = Output(UInt(width.W))
    val done     = Output(Bool())
  })

  // Simple non-restoring division
  val busy = RegInit(false.B)
  val cnt  = RegInit(0.U(log2Ceil(width+1).W))
  val quot = RegInit(0.U(width.W))
  val rem  = RegInit(0.U((width+1).W))
  val neg_quot = RegInit(false.B)
  val neg_rem  = RegInit(false.B)
  val divisor_reg = RegInit(0.U(width.W))

  io.done := !busy
  io.quotient  := Mux(neg_quot, (~quot + 1.U), quot)
  io.remainder := Mux(neg_rem,  (~rem(width-1, 0) + 1.U), rem(width-1, 0))

  when (io.start && !busy) {
    val div = io.dividend
    val divsr = io.divisor
    val sgn_a = io.signed && div(width-1)
    val sgn_b = io.signed && divsr(width-1)
    neg_quot := sgn_a ^ sgn_b
    neg_rem  := sgn_a
    val abs_a = Mux(sgn_a, (~div + 1.U), div)
    val abs_b = Mux(sgn_b, (~divsr + 1.U), divsr)
    rem := Cat(0.U(1.W), abs_a)
    divisor_reg := abs_b
    quot := 0.U
    cnt := (width).U
    busy := true.B
  }.elsewhen(busy) {
    val next_rem = Cat(rem(width-1,0), quot(width-1)) - Cat(0.U(1.W), divisor_reg)
    when (next_rem(width)) {
      quot := Cat(quot(width-2, 0), 0.U(1.W))
      rem  := rem
    }.otherwise {
      quot := Cat(quot(width-2, 0), 1.U(1.W))
      rem  := next_rem
    }
    cnt := cnt - 1.U
    when (cnt === 1.U) {
      busy := false.B
    }
  }
}
