package common

import chisel3._
import chisel3.util._

// Math utilities for hardware
object MathUtil {
  // Count leading zeros of an n-bit value
  def countLeadingZeros(x: UInt, n: Int): UInt = {
    val bits = (n-1 to 0 by -1).map(i => x(i))
    val found = Wire(Vec(n, Bool()))
    val counts = Wire(Vec(n+1, UInt(log2Ceil(n+1).W)))
    counts(0) := 0.U
    for (i <- 0 until n) {
      found(i) := bits(i)
      counts(i+1) := counts(i)
    }
    PriorityMux(bits.zip(0 until n).map { case (b, i) => b -> (n-1-i).U } :+ (true.B -> n.U))
  }

  // Integer log2, rounding down
  def log2Floor(x: Int): Int = if (x <= 1) 0 else 1 + log2Floor(x >> 1)

  // Round up to next power of 2
  def nextPow2(x: Int): Int = {
    var n = 1
    while (n < x) n <<= 1
    n
  }

  // Absolute value of SInt
  def abs(x: SInt): UInt = Mux(x < 0.S, (-x).asUInt, x.asUInt)
}
