class FifoX[T <: Data](gen: T, depth: Int) extends Module {
  val io = IO(new Bundle {
    val enq   = Flipped(Decoupled(gen))
    val deq   = Decoupled(gen)
    val count = Output(UInt(log2Ceil(depth + 1).W))
  })

  val q = Module(new Queue(gen, depth))
  q.io.enq <> io.enq
  io.deq   <> q.io.deq
  io.count := q.io.count
}

