import chisel3._
import chisel3.util._

// Integer divider (non-pipelined, iterative, restoring algorithm)
class IDiv(width: Int) extends Module {
  val io = IO(new Bundle {
    val dividend  = Input(UInt(width.W))
    val divisor   = Input(UInt(width.W))
    val signed    = Input(Bool())
    val start     = Input(Bool())
    val quotient  = Output(UInt(width.W))
    val remainder = Output(UInt(width.W))
    val done      = Output(Bool())
  })

  val busy        = RegInit(false.B)
  val cnt         = RegInit(0.U(log2Ceil(width + 1).W))
  val quot        = RegInit(0.U(width.W))
  val rem         = RegInit(0.U((width + 1).W))
  val negQuot     = RegInit(false.B)
  val negRem      = RegInit(false.B)
  val divisorReg  = RegInit(0.U(width.W))

  io.done      := !busy
  io.quotient  := Mux(negQuot, (~quot + 1.U), quot)
  io.remainder := Mux(negRem,  (~rem(width - 1, 0) + 1.U), rem(width - 1, 0))

  when(io.start && !busy) {
    val sgnA = io.signed && io.dividend(width - 1)
    val sgnB = io.signed && io.divisor(width - 1)
    negQuot    := sgnA ^ sgnB
    negRem     := sgnA
    val absA   = Mux(sgnA, (~io.dividend + 1.U), io.dividend)
    val absB   = Mux(sgnB, (~io.divisor  + 1.U), io.divisor)
    rem        := Cat(0.U(1.W), absA)
    divisorReg := absB
    quot       := 0.U
    cnt        := width.U
    busy       := true.B
  }.elsewhen(busy) {
    // Restoring step: shift rem left by 1, bring in next quot bit, subtract divisor
    val shifted  = Cat(rem(width - 1, 0), quot(width - 1))
    val diff     = shifted - Cat(0.U(1.W), divisorReg)
    when(diff(width)) {
      // Remainder went negative – restore and shift in 0
      quot := Cat(quot(width - 2, 0), 0.U(1.W))
      // rem stays unchanged (restored)
    }.otherwise {
      quot := Cat(quot(width - 2, 0), 1.U(1.W))
      rem  := diff
    }
    cnt := cnt - 1.U
    when(cnt === 1.U) {
      busy := false.B
    }
  }
}

