/** Hardware and Scala-elaboration math utilities. */
object MathUtil {

  /** Count leading zeros of an n-bit UInt value (hardware). */
  def countLeadingZeros(x: UInt, n: Int): UInt = {
    // Build a sequence of (bit, index) pairs from MSB to LSB
    val pairs = (n - 1 to 0 by -1).map(i => x(i) -> (n - 1 - i).U(log2Ceil(n + 1).W))
    // Return the index of the first '1' bit, or n if all zeros
    PriorityMux(pairs :+ (true.B -> n.U(log2Ceil(n + 1).W)))
  }

  /** Integer log2, rounding down (Scala elaboration time). */
  def log2Floor(x: Int): Int = if (x <= 1) 0 else 1 + log2Floor(x >> 1)

  /** Round up to the next power of two (Scala elaboration time). */
  def nextPow2(x: Int): Int = {
    var n = 1
    while (n < x) n <<= 1
    n
  }

  /** Absolute value of a signed integer, returned as UInt (hardware). */
  def abs(x: SInt): UInt = Mux(x < 0.S, (-x).asUInt, x.asUInt)
}

