// A single-cycle pipeline slice: a 1-entry pipe-mode Queue giving a
// registered ready/valid cut that does not stall the producer.
class Slice[T <: Data](gen: T) extends Module {
  val io = IO(new Bundle {
    val in  = Flipped(Decoupled(gen))
    val out = Decoupled(gen)
  })

  // pipe=true allows the queue to be filled and drained in the same cycle
  val q = Module(new Queue(gen, 1, pipe = true))
  q.io.enq <> io.in
  io.out   <> q.io.deq
}

